def merge_sorted_streams(*streams):
    """
    Merge multiple sorted streams of (key, value) tuples into a single sorted output.
    For duplicate keys, the last value seen (from later streams or later positions) wins.
    """
    # Create iterators for each stream
    iterators = [iter(s) for s in streams]

    # Track the current head of each iterator
    # Each entry is (key, value, stream_index) or None if exhausted
    heads = []
    for idx, it in enumerate(iterators):
        try:
            key, value = next(it)
            heads.append((key, value, idx))
        except StopIteration:
            heads.append(None)

    # We need to handle the "last value wins" rule for duplicate keys.
    # Since streams are sorted by key, we can process keys in order.
    # When we see a key, we need to collect all values for that key from all streams
    # that have this key at their current head, and take the last one.

    while any(h is not None for h in heads):
        # Find the minimum key among all active heads
        min_key = None
        for h in heads:
            if h is not None:
                if min_key is None or h[0] < min_key:
                    min_key = h[0]

        if min_key is None:
            break

        # Collect all values for this min_key from all streams
        # The last one (by stream index order, since we iterate in order) wins
        last_value = None
        for idx, h in enumerate(heads):
            if h is not None and h[0] == min_key:
                last_value = h[1]
                # Advance this iterator
                it = iterators[idx]
                try:
                    key, value = next(it)
                    heads[idx] = (key, value, idx)
                except StopIteration:
                    heads[idx] = None

        if last_value is not None:
            yield (min_key, last_value)
